<script>
  let { savingPlan = $bindable(null) } = $props();
  let monthlySaving = $state(1750); let months = $state(12);
  const savingRanges=[['$500 - $1,000',750],['$1,001 - $2,500',1750],['$2,501 - $5,000',3750],['$5,001 - $10,000',7500],['Más de $10,000',12500]];
  let total = $derived(Number(monthlySaving) * Number(months));
  function sendPlan(){ savingPlan={monthlySaving:Number(monthlySaving),months:Number(months),total}; document.getElementById('formulario-captacion')?.scrollIntoView({behavior:'smooth'}); }
</script>
<section id="simulador" class="py-16 sm:py-20"><div class="mx-auto grid max-w-7xl gap-8 px-4 sm:px-6 lg:grid-cols-[.85fr_1.15fr] lg:px-8"><div><p class="eyebrow">Planea a tu ritmo</p><h2 class="mt-3 text-3xl font-extrabold sm:text-4xl">Calcula tu capacidad de ahorro</h2><p class="muted mt-4 leading-relaxed">Esta herramienta te ayuda a visualizar un hábito de ahorro. No calcula descuentos, convenios ni el monto de una liquidación.</p></div><div class="card rounded-2xl p-6 sm:p-8"><div class="grid gap-6 sm:grid-cols-2"><label class="font-semibold">¿Cuánto podrías apartar al mes?<select class="field mt-2" bind:value={monthlySaving} aria-describedby="ahorro-ayuda"><option value="" disabled>Rango mensual</option>{#each savingRanges as range}<option value={range[1]}>{range[0]}</option>{/each}</select><span id="ahorro-ayuda" class="muted mt-2 block text-xs font-normal">Elige un rango aproximado que no comprometa tus gastos básicos.</span></label><label class="font-semibold">¿Durante cuántos meses?<select class="field mt-2" bind:value={months}><option value="6">6 meses</option><option value="12">12 meses</option><option value="18">18 meses</option><option value="24">24 meses</option></select></label></div><div class="mt-6 rounded-xl p-5" style="background:var(--brand-soft)"><p class="muted text-sm">Podrías reunir aproximadamente</p><p class="mt-1 text-3xl font-extrabold" style="color:var(--brand)">${total.toLocaleString('es-MX')} MXN</p><p class="muted mt-2 text-xs leading-relaxed">La cantidad real que necesites y las alternativas disponibles dependen de tu caso y serán explicadas por un asesor.</p></div><button class="btn-primary focus-ring mt-6 rounded-lg px-5 py-3 font-bold" onclick={sendPlan}><span class="button-label">Usar esta estimación al revisar mi caso</span></button></div></div></section>
